static size_t unhex(const char *h, u8 *out, size_t max)
{
	size_t n = 0;
	while (h[0] && h[1] && n < max) {
		unsigned v;
		sscanf(h, "%2x", &v);
		out[n++] = (u8)v;
		h += 2;
	}
	return n;
}

static void md5hex(const u8 *p, size_t n, char *out)
{
	u8 d[16];
	ln_md5(p, n, d);
	t_hex(d, 16, out);
}

static void dsi(void)
{
	u8 h[DSI_HDR];
	DsiHdr d;
	dsi_put_header(h, DSI_REQUEST, DSI_WRITE, 0xbeef, 20, 20 + 65536);
	CHECK_HEX(h, 16, "0006beef0000001400010014" "00000000");
	dsi_put_header(h, DSI_REPLY, DSI_COMMAND, 7, (u32)kFPObjectNotFound, 0);
	dsi_get_header(h, &d);
	CHECK_INT(d.flags, 1);
	CHECK_INT(d.cmd, 2);
	CHECK_INT(d.id, 7);
	CHECK_INT((s32)d.code, -5018);
	CHECK_INT(d.len, 0);
	CHECK_HEX(h, 8, "01020007ffffec66");
}

static void packing(void)
{
	u8 mem[64];
	AfpBuf b;
	afp_b_init(&b, mem, sizeof(mem));
	afp_b_u8(&b, FPGetFileDirParms);
	afp_b_u8(&b, 0);
	afp_b_u16(&b, 1);
	afp_b_u32(&b, AFP_ROOT_DID);
	afp_b_path(&b, "dir/Caf\xc3\xa9");          /* NFC in, NFD on the wire, NUL separator */
	CHECK_INT(b.err, 0);
	CHECK_HEX(mem, b.len, "2200000100000002" "03" "00000000" "000a" "64697200436166" "65cc81");
	afp_b_init(&b, mem, sizeof(mem));
	afp_b_u8(&b, FPLogin);
	afp_b_pstr(&b, "AFP3.4");
	afp_b_pad(&b);
	CHECK_INT(b.len, 8);
	afp_b_name3(&b, "bob");
	CHECK_HEX(mem + 8, 6, "030003626f62");
	afp_b_u64(&b, 0x0102030405060708ULL);
	CHECK_HEX(mem + 14, 8, "0102030405060708");
	/* overflow is sticky */
	afp_b_init(&b, mem, 4);
	afp_b_u32(&b, 1);
	afp_b_u8(&b, 1);
	CHECK_INT(b.err, 1);
	afp_b_init(&b, mem, 8);
	afp_b_path(&b, "a-long-name");
	CHECK_INT(b.err, 1);
	/* empty path = the directory itself */
	afp_b_init(&b, mem, sizeof(mem));
	afp_b_path(&b, "");
	CHECK_HEX(mem, b.len, "03000000000000");
}

static void dates(void)
{
	CHECK_INT(afp_date_to_unix(0), 946684800);
	CHECK_INT(afp_date_from_unix(946684800), 0);
	CHECK_INT(afp_date_to_unix(0xffffffffu), 946684799);       /* -1 */
	CHECK_INT(afp_date_from_unix(0), 0xc792bc80u);              /* 1970 is before 2000 */
	CHECK_INT(afp_date_to_unix(0xc792bc80u), 0);
	CHECK_INT(afp_date_to_unix(AFP_DATE_NONE), 0);
	CHECK_INT(afp_date_to_unix(afp_date_from_unix(1793332355u)), 1793332355u);
}

