static void srvinfo(void)
{
	u8 buf[512];
	size_t n = unhex(status_hex, buf, sizeof(buf));
	AfpSrvInfo si;
	CHECK_INT(n, 405);
	CHECK_INT(afp_parse_srvinfo(buf, n, &si), LN_OK);
	CHECK_STR(si.machine, "Netatalk3.1.18");
	CHECK_STR(si.name, "vm");
	CHECK_INT(si.version, 34);
	CHECK_STR(si.version_str, "AFP3.4");
	CHECK_INT(si.uams, UAM_GUEST | UAM_CLEARTXT | UAM_DHX2);
	CHECK(si.flags & AFPSRV_TCPIP);
	CHECK(si.flags & AFPSRV_UTF8NAME);
	/* truncated replies do not crash */
	CHECK_INT(afp_parse_srvinfo(buf, 8, &si), LN_EPROTO);
	CHECK_INT(afp_parse_srvinfo(buf, 60, &si), LN_OK);
}

static void params(void)
{
	/* a file: attributes, mod date, node id, ext data fork length, UTF-8
	 * name (decomposed), UNIX privileges */
	u8 p[128];
	AfpParams a;
	u16 bm = FDBIT_ATTR | FDBIT_MDATE | FDBIT_NODEID | FBIT_XDFLEN | FDBIT_UTF8NAME | FDBIT_UNIXPR;
	size_t n = 0;
	ln_put_be16(p + n, ATTR_INVISIBLE | ATTR_WRITEINHIBIT); n += 2;
	ln_put_be32(p + n, 100); n += 4;                       /* 2000-01-01 00:01:40 */
	ln_put_be32(p + n, 4711); n += 4;
	ln_put_be64(p + n, 0x123456789ULL); n += 8;
	ln_put_be16(p + n, 40); n += 2;                        /* name offset */
	ln_put_be32(p + n, 0); n += 4;
	ln_put_be32(p + n, 501); n += 4;
	ln_put_be32(p + n, 20); n += 4;
	ln_put_be32(p + n, 0100644); n += 4;
	ln_put_be32(p + n, 0x87040404); n += 4;                /* user: owner+rw+search */
	CHECK_INT(n, 40);
	ln_put_be32(p + n, 0x08000103); n += 4;                /* text encoding hint */
	ln_put_be16(p + n, 7); n += 2;
	memcpy(p + n, "e\xcc\x81t\xc3\xa9", 6);               /* "e" + U+0301, "t", NFC e-acute */
	n += 7;
	p[n - 1] = 'x';
	CHECK_INT(afp_parse_params(p, n, bm, 0, &a), LN_OK);
	CHECK_INT(a.attr, ATTR_INVISIBLE | ATTR_WRITEINHIBIT);
	CHECK_INT(a.mdate, 946684900);
	CHECK_INT(a.nodeid, 4711);
	CHECK_INT(a.size, 0x123456789ULL);
	CHECK_STR(a.name, "\xc3\xa9t\xc3\xa9x");
	CHECK_INT(a.has_unix, 1);
	CHECK_INT(a.uid, 501);
	CHECK_INT(a.perms, 0100644);
	/* the name offset pointing past the end */
	CHECK_INT(afp_parse_params(p, 30, bm, 0, &a), LN_EPROTO);
	/* a directory: offspring count is 2 bytes where files have 4 */
	n = 0;
	ln_put_be16(p + n, 0); n += 2;
	ln_put_be32(p + n, 2); n += 4;                         /* node id */
	ln_put_be16(p + n, 9); n += 2;                         /* offspring */
	CHECK_INT(afp_parse_params(p, n, FDBIT_ATTR | FDBIT_NODEID | DBIT_OFFCNT, 1, &a), LN_OK);
	CHECK_INT(a.nodeid, 2);
	CHECK_INT(a.offspring, 9);
	CHECK_INT(a.isdir, 1);
}

static void cast128(void)
{
	static const u8 key[16] = { 0x01, 0x23, 0x45, 0x67, 0x12, 0x34, 0x56, 0x78, 0x23, 0x45, 0x67, 0x89, 0x34, 0x56, 0x78, 0x9a };
	static const u8 pt[8] = { 0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef };
	LnCast128 c;
	u8 o[8], d[8], buf[24], iv[8];
	ln_cast128_setkey(&c, key, 16);
	ln_cast128_encrypt(&c, pt, o);
	CHECK_HEX(o, 8, "238b4fe5847e44b2");
	ln_cast128_decrypt(&c, o, d);
	CHECK(!memcmp(d, pt, 8));
	ln_cast128_setkey(&c, key, 10);
	ln_cast128_encrypt(&c, pt, o);
	CHECK_HEX(o, 8, "eb6a711a2c02271b");
	ln_cast128_decrypt(&c, o, d);
	CHECK(!memcmp(d, pt, 8));
	ln_cast128_setkey(&c, key, 5);
	ln_cast128_encrypt(&c, pt, o);
	CHECK_HEX(o, 8, "7ac816d16e9b302e");
	ln_cast128_decrypt(&c, o, d);
	CHECK(!memcmp(d, pt, 8));
	/* RFC 2144 B.2 maintenance test, shortened to 10000 iterations
	 * (the full 1,000,000 runs with T_AFP_FULL=1) */
	{
		u8 a[16], b[16];
		long i, iters = getenv("T_AFP_FULL") ? 1000000L : 10000L;
		LnCast128 ka, kb;
		memcpy(a, key, 16);
		memcpy(b, key, 16);
		for (i = 0; i < iters; i++) {
			ln_cast128_setkey(&kb, b, 16);
			ln_cast128_encrypt(&kb, a, a);
			ln_cast128_encrypt(&kb, a + 8, a + 8);
			ln_cast128_setkey(&ka, a, 16);
			ln_cast128_encrypt(&ka, b, b);
			ln_cast128_encrypt(&ka, b + 8, b + 8);
		}
		if (iters == 1000000L) {
			CHECK_HEX(a, 16, "eea9d0a249fd3ba6b3436fb89d6dca92");
			CHECK_HEX(b, 16, "b2c95eb00c31ad7180ac05b8e83d696e");
		} else {
			/* computed with Python's CAST5 for 10000 iterations */
			CHECK_HEX(a, 16, T_CAST_A10K);
			CHECK_HEX(b, 16, T_CAST_B10K);
		}
	}
	/* CBC round trip, IV "LWallace" */
	memcpy(iv, "LWallace", 8);
	memcpy(buf, "0123456789abcdefFEDCBA98", 24);
	ln_cast128_setkey(&c, key, 16);
	ln_cast128_cbc_encrypt(&c, iv, buf, 24);
	CHECK_HEX(buf, 24, T_CAST_CBC);
	ln_cast128_cbc_decrypt(&c, iv, buf, 24);
	CHECK(!memcmp(buf, "0123456789abcdefFEDCBA98", 24));
}

static void bignum(void)
{
	u8 base[256], ex[64], mod[256], out[256];
	char h[40];
	size_t bl = unhex(mx_base_hex, base, sizeof(base)), el = unhex(mx_exp_hex, ex, sizeof(ex));
	size_t ml;
	/* p from the DHX2 vector (Oakley group 2) */
	unhex(dhx2_reply1_hex + 16, mod, 128);
	ml = 128;
	CHECK_INT(ln_bn_modexp(out, base, bl, ex, el, mod, ml), LN_OK);
	CHECK_HEX(out, 16, MX_RESULT_HEAD);
	md5hex(out, 128, h);
	CHECK_STR(h, MX_RESULT_MD5);
	/* 2^521 - 1 */
	memset(mod, 0xff, 66);
	mod[0] = 0x01;
	{
		u8 three = 3;
		el = unhex(mx3_exp_hex, ex, sizeof(ex));
		CHECK_INT(ln_bn_modexp(out, &three, 1, ex, el, mod, 66), LN_OK);
		CHECK_HEX(out, 66, MX3_RESULT);
	}
	/* small ones: 3^5 mod 7 = 5, x^0 = 1, leading zero bytes in the modulus */
	{
		u8 b3 = 3, e5 = 5, m7[3] = { 0, 0, 7 }, e0 = 0, r[3];
		CHECK_INT(ln_bn_modexp(r, &b3, 1, &e5, 1, m7, 3), LN_OK);
		CHECK_HEX(r, 3, "000005");
		CHECK_INT(ln_bn_modexp(r, &b3, 1, &e0, 1, m7, 3), LN_OK);
		CHECK_HEX(r, 3, "000001");
		m7[2] = 8;
		CHECK_INT(ln_bn_modexp(r, &b3, 1, &e5, 1, m7, 3), LN_EINVAL);   /* even modulus */
	}
	/* base bigger than the modulus */
	{
		u8 b[4] = { 1, 0, 0, 1 }, e = 1, m = 0xfb, r;              /* 16777217 mod 251 */
		CHECK_INT(ln_bn_modexp(&r, b, 4, &e, 1, &m, 1), LN_OK);
		CHECK_INT(r, 16777217 % 251);
	}
	CHECK(ln_bn_cmp((const u8 *)"\0\x05", 2, (const u8 *)"\x05", 1) == 0);
	CHECK(ln_bn_cmp((const u8 *)"\x01\x00", 2, (const u8 *)"\xff", 1) > 0);
}

static void dhx2(void)
{
	u8 rep[300], ra[32], out[300];
	AfpDhx *x = ln_alloc(sizeof(*x));
	char h[40];
	size_t n = unhex(dhx2_reply1_hex, rep, sizeof(rep)), l;
	unhex(dhx2_ra_hex, ra, sizeof(ra));
	CHECK_INT(afp_dhx2_reply1(x, rep, n, ra, 32), LN_OK);
	CHECK_INT(x->id, 0x1234);
	CHECK_INT(x->plen, 128);
	md5hex(x->ma, 128, h);
	CHECK_STR(h, DHX2_MA_MD5);
	CHECK_HEX(x->key, 16, DHX2_K);
	for (l = 0; l < 16; l++)
		x->cnonce[l] = (u8)(0x11 + l);
	l = afp_dhx2_cont1(x, out);
	CHECK_INT(l, 128 + 16);
	md5hex(out, l, h);
	CHECK_STR(h, DHX2_CONT1_MD5);
	n = unhex(dhx2_reply2_hex, rep, sizeof(rep));
	CHECK_INT(afp_dhx2_reply2(x, rep, n), LN_OK);
	CHECK_INT(x->id, 0x1235);
	CHECK_HEX(x->snonce, 16, "a0a1a2a3a4a5a6a7a8a9aaabacadaeaf");
	l = afp_dhx2_cont2(x, "lagoon-test-pw", out);
	CHECK_INT(l, 272);
	md5hex(out, l, h);
	CHECK_STR(h, DHX2_CONT2_MD5);
	/* a server that does not know the key fails the nonce check */
	rep[5] ^= 1;
	CHECK_INT(afp_dhx2_reply2(x, rep, n), LN_EAUTH);
	/* degenerate public key Mb = 1 is refused */
	n = unhex(dhx2_reply1_hex, rep, sizeof(rep));
	memset(rep + 8 + 128, 0, 128);
	rep[8 + 255] = 1;
	CHECK_INT(afp_dhx2_reply1(x, rep, n, ra, 32), LN_EPROTO);
	/* nonce increment carries */
	{
		u8 nn[16];
		memset(nn, 0xff, 16);
		nn[0] = 0x7f;
		afp_nonce_inc(nn);
		CHECK_HEX(nn, 16, "80000000000000000000000000000000");
	}
	ln_free(x);
}

static void dhcast(void)
{
	u8 rep[64], ra[16], out[100];
	AfpDhx *x = ln_alloc(sizeof(*x));
	char h[40];
	size_t n, l;
	unhex(dhc_ra_hex, ra, sizeof(ra));
	afp_dhcast_ma(x, ra, 16);
	CHECK_HEX(x->ma, 16, DHC_MA);
	n = unhex(dhc_reply_hex, rep, sizeof(rep));
	CHECK_INT(afp_dhcast_reply(x, rep, n, ra, 16), LN_OK);
	CHECK_INT(x->id, 0x0777);
	CHECK_HEX(x->key, 16, DHC_K);
	CHECK_HEX(x->snonce, 16, "505152535455565758595a5b5c5d5e5f");
	l = afp_dhcast_cont(x, "lagoon-test-pw", out);
	CHECK_INT(l, 80);
	md5hex(out, l, h);
	CHECK_STR(h, DHC_CONT_MD5);
	ln_free(x);
}

int main(void)
{
	dsi();
	packing();
	dates();
	errors();
	srvinfo();
	params();
	cast128();
	bignum();
	dhx2();
	dhcast();
	T_DONE("t_afp_unit");
}
